// 1. 基本 Record 定义
public record Point(int x, int y) {}

Point p = new Point(3, 5);
System.out.println(p.x());          // 3（访问器方法，非 getX）
System.out.println(p);              // Point[x=3, y=5]（自动 toString）
System.out.println(p.equals(new Point(3, 5))); // true

// 2. 带参数校验的紧凑构造器
public record Range(int start, int end) {
    public Range {
        if (start > end) {
            throw new IllegalArgumentException("start must <= end");
        }
    }
}

// 3. 实现接口
public record UserDTO(String name, String email)
    implements Serializable {
    // 可以添加自定义方法
    public String displayName() {
        return name.substring(0, 1).toUpperCase() + name.substring(1);
    }
}

// 4. 作为方法返回多个值
public record Pair<A, B>(A first, B second) {}
public Pair<String, Integer> findUser(int id) {
    return new Pair<>("Alice", 25);
}
